text = input("문장: ")
upper = lower = digit = space = 0
for ch in text:
    if ch.isupper():
        upper += 1
    elif ch.islower():
        lower += 1
    elif ch.isdigit():
        digit += 1
    elif ch.isspace():
        space += 1
print(f"대문자 {upper}, 소문자 {lower}, 숫자 {digit}, 공백 {space}")
